+        provisionalDowngradedObserved = true;
+      }
+    }
+  }
+  provisionalSafeDowngradedNonFactOnly =
+    provisionalSafeDowngradedNonFactOnly && provisionalDowngradedObserved;
+
+  const missingAcceptedSemanticContextPreservesRows = fixtureList
+    .filter((fixture) => fixture.fixture_id !== 'accepted_semantic_ready')
+    .every((fixture) => {
+      const preserved = fixture.payload?.row_presence?.included === true;
+      const semanticStatus = fixture.payload?.semantic_context?.status ?? 'missing';
+      const missingAccepted =
+        semanticStatus !== 'accepted_available' ||
+        arrayFrom(fixture.payload?.semantic_context?.accepted_answer_fact_assertion_ids).length === 0;
+      if (missingAccepted && !preserved) errors.push('missing_semantic_context_row_removed');
+      return !missingAccepted || preserved;
+    });
+
+  const fallbackOnly = fixtureList.find((fixture) => fixture.fixture_id === 'fallback_only');
+  const fallbackManifest = manifestEntryById(manifest, 'fallback_only');
+  const fallbackOnlyStatePresentWithManifestDerivationNote =
+    fallbackOnly?.payload?.display_posture === 'fallback_only' &&
+    fallbackOnly?.payload?.row_presence?.included === true &&
+    fallbackOnly?.source_selection?.source_derivation_kind === 'frontend_projection' &&
+    typeof fallbackOnly?.source_selection?.derivation_reason === 'string' &&
+    fallbackManifest?.source_derivation_kind === 'frontend_projection' &&
+    String(fallbackManifest?.derivation_reason).includes('no_native_fallback_only_rows');
+
+  const manifestHasSourceRowsAndPolicyNotes = fixtureList.every((fixture) => {
+    const entry = manifestEntryById(manifest, fixture.fixture_id);
+    return entry?.source_row_id === fixture.source_selection.source_row_id &&
+      arrayFrom(entry?.source_artifact_refs).length > 0 &&
+      arrayFrom(entry?.expected_ui_policy_notes).length > 0;
