+    derived_from_source_payload: fixture.source_selection.derived_from_source_payload,
+    derivation_reason: fixture.source_selection.derivation_reason ?? null,
+    rag_lite_read_path_case: fixture.source_selection.rag_lite_read_path_case,
+    payload_validation_status: fixture.validation.status,
+    rag_eligible: fixture.payload?.rag_context?.eligible === true,
+    student_display_available:
+      fixture.payload?.student_facing_availability?.student_display_available === true,
+    student_attempt_available:
+      fixture.payload?.student_facing_availability?.student_attempt_available === true,
+    display_posture: fixture.payload?.display_posture ?? null,
+    semantic_context_status: fixture.payload?.semantic_context?.status ?? 'missing',
+    fallback_posture: fixture.payload?.fallback_posture?.mode ?? null,
+    source_artifact_refs: fixture.source_selection.source_artifact_refs,
+    expected_ui_policy_notes: fixture.expected_ui_policy_notes,
+  }));
+  const base = {
+    schema_version: MANIFEST_SCHEMA_VERSION,
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    depends_on_issues: [...DEPENDS_ON_ISSUES],
+    subject_code: SUBJECT_CODE,
+    manifest_status: 'ready',
+    output_artifacts: {
+      fixtures: paths.fixturesOut,
+      manifest: paths.manifestOut,
+      validator: paths.validatorOut,
+      readback: paths.readbackOut,
+    },
+    source_artifacts: fixturesArtifact.source_artifacts,
+    summary: fixturesArtifact.summary,
+    fixture_manifest: fixtureManifest,
+    no_frontend_ui_integration_claim: true,
+  };
+  return {
+    ...base,
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        schema_version: base.schema_version,
+        fixture_manifest: base.fixture_manifest,
+        summary: base.summary,
+      }),
+    },
+  };
+}
+
+function check(status, id, details = {}) {
+  return { id, status: status === true ? 'pass' : 'fail', ...details };
+}
+
+function manifestEntryById(manifest, fixtureId) {
+  return arrayFrom(manifest?.fixture_manifest)
+    .find((entry) => entry?.fixture_id === fixtureId) ?? null;
+}
+
+function validateQuestionRuntimePayloadFrontendFixtures({
+  fixtures,
+  manifest,
+  schema,
+  boundary,
+  all3530Result,
+} = {}) {
+  const errors = [];
+  const fixtureList = arrayFrom(fixtures?.fixtures);
+  if (!isRecord(fixtures)) errors.push('fixtures_required');
+  if (!isRecord(manifest)) errors.push('manifest_required');
+  if (!isRecord(schema)) errors.push('schema_required');
+  if (!isRecord(boundary)) errors.push('boundary_required');
+
+  const fixtureIds = fixtureList.map((fixture) => fixture.fixture_id);
+  const requiredStatesPresent = REQUIRED_FIXTURE_IDS.every((fixtureId) => fixtureIds.includes(fixtureId));
+  const sourceRowsByQuestion = mapByQuestion(all3530Result?.readModel?.rows);
+  const sourceRowsSelectedFromAll3530 = fixtureList.every((fixture) => {
+    const sourceRow = sourceRowsByQuestion.get(fixture?.source_selection?.source_row_id);
+    return sourceRow?.row_presence_included === true &&
+      sourceRow?.question_key === fixture?.source_selection?.source_row_id;
+  });
+  const validationResults = fixtureList.map((fixture) => validateQuestionRuntimePayload({
+    schema,
+    payload: fixture.payload,
+    boundary,
+    fixtureId: fixture.fixture_id,
+  }));
+  for (const validation of validationResults) {
+    for (const error of validation.errors) errors.push(error);
+  }
+  const allPayloadsValidate = validationResults.every((validation) => validation.status === 'pass');
+
+  const ragEligibleAndIneligiblePresent =
+    fixtureList.some((fixture) => fixture.payload?.rag_context?.eligible === true) &&
+    fixtureList.some((fixture) => fixture.payload?.rag_context?.eligible === false);
+
+  const attemptDegradedBlockedPosturesCovered =
+    fixtureList.some((fixture) => (
+      fixture.payload?.student_facing_availability?.student_attempt_available === true &&
+      fixture.payload?.fallback_posture?.mode === 'none'
+    )) &&
+    fixtureList.some((fixture) => fixture.payload?.fallback_posture?.mode === 'degraded') &&
+    fixtureList.some((fixture) => (
+      fixture.payload?.student_facing_availability?.availability_posture === 'blocked'
+    ));
+
+  let provisionalSafeDowngradedNonFactOnly = true;
+  let provisionalDowngradedObserved = false;
+  for (const fixture of fixtureList) {
+    const answerFactIds = new Set(arrayFrom(fixture.payload?.rag_context?.answer_fact_assertion_ids));
+    for (const assertion of arrayFrom(fixture.payload?.semantic_context?.provisional_assertions)) {
+      if (assertion?.answer_fact_eligible === true || answerFactIds.has(assertion?.assertion_id)) {
+        provisionalSafeDowngradedNonFactOnly = false;
+        errors.push('provisional_safe_promoted_to_answer_fact');
+      }
+      if (
+        fixture.payload?.semantic_context?.status === 'provisional_only' &&
+        assertion?.downgraded_context_eligible === true
+      ) {
+        provisionalDowngradedObserved = true;
+      }
+    }
+  }
+  provisionalSafeDowngradedNonFactOnly =
+    provisionalSafeDowngradedNonFactOnly && provisionalDowngradedObserved;
+
+  const missingAcceptedSemanticContextPreservesRows = fixtureList
+    .filter((fixture) => fixture.fixture_id !== 'accepted_semantic_ready')
+    .every((fixture) => {
+      const preserved = fixture.payload?.row_presence?.included === true;
+      const semanticStatus = fixture.payload?.semantic_context?.status ?? 'missing';
+      const missingAccepted =
+        semanticStatus !== 'accepted_available' ||
+        arrayFrom(fixture.payload?.semantic_context?.accepted_answer_fact_assertion_ids).length === 0;
+      if (missingAccepted && !preserved) errors.push('missing_semantic_context_row_removed');
+      return !missingAccepted || preserved;
+    });
+
+  const fallbackOnly = fixtureList.find((fixture) => fixture.fixture_id === 'fallback_only');
+  const fallbackManifest = manifestEntryById(manifest, 'fallback_only');
+  const fallbackOnlyStatePresentWithManifestDerivationNote =
+    fallbackOnly?.payload?.display_posture === 'fallback_only' &&
+    fallbackOnly?.payload?.row_presence?.included === true &&
+    fallbackOnly?.source_selection?.source_derivation_kind === 'frontend_projection' &&
+    typeof fallbackOnly?.source_selection?.derivation_reason === 'string' &&
+    fallbackManifest?.source_derivation_kind === 'frontend_projection' &&
+    String(fallbackManifest?.derivation_reason).includes('no_native_fallback_only_rows');
+
+  const manifestHasSourceRowsAndPolicyNotes = fixtureList.every((fixture) => {
+    const entry = manifestEntryById(manifest, fixture.fixture_id);
+    return entry?.source_row_id === fixture.source_selection.source_row_id &&
+      arrayFrom(entry?.source_artifact_refs).length > 0 &&
+      arrayFrom(entry?.expected_ui_policy_notes).length > 0;
+  });
+
+  const frontendUiIntegrationNotPerformed =
+    fixtures?.frontend_ui_integration_performed === false &&
+    manifest?.no_frontend_ui_integration_claim === true;
+
+  const checks = [
+    check(
+      allPayloadsValidate,
+      'all_fixture_payloads_validate_against_question_runtime_payload_schema',
+    ),
+    check(
+      attemptDegradedBlockedPosturesCovered,
+      'attempt_degraded_blocked_postures_covered',
+    ),
+    check(
+      fallbackOnlyStatePresentWithManifestDerivationNote,
+      'fallback_only_state_present_with_manifest_derivation_note',
+    ),
+    check(frontendUiIntegrationNotPerformed, 'frontend_ui_integration_not_performed'),
+    check(manifestHasSourceRowsAndPolicyNotes, 'manifest_has_source_rows_and_policy_notes'),
+    check(
+      missingAcceptedSemanticContextPreservesRows,
+      'missing_accepted_semantic_context_preserves_rows',
+    ),
+    check(provisionalSafeDowngradedNonFactOnly, 'provisional_safe_downgraded_non_fact_only'),
+    check(ragEligibleAndIneligiblePresent, 'rag_eligible_and_ineligible_states_present'),
+    check(requiredStatesPresent, 'required_frontend_fixture_states_present', {
+      required_fixture_ids: REQUIRED_FIXTURE_IDS,
+      fixture_ids: fixtureIds,
+    }),
+    check(sourceRowsSelectedFromAll3530, 'source_rows_selected_from_all_3530_read_model'),
+  ].sort(compareCheckIds);
+
+  for (const failed of checks.filter((item) => item.status === 'fail')) {
+    errors.push(`check_failed:${failed.id}`);
+  }
+
+  const uniqueErrors = [...new Set(errors)];
+  const status = uniqueErrors.length === 0 ? 'pass' : 'fail';
+  const summary = {
+    validation_status: status,
+    fixture_count: fixtureList.length,
+    required_state_count: fixtureList.filter((fixture) => fixture.required_state === true).length,
+    schema_valid_fixture_count: validationResults.filter((validation) => validation.status === 'pass').length,
+    schema_invalid_fixture_count: validationResults.filter((validation) => validation.status !== 'pass').length,
+    check_count: checks.length,
+    check_pass_count: checks.filter((item) => item.status === 'pass').length,
+    check_fail_count: checks.filter((item) => item.status === 'fail').length,
+    native_semantic_unavailable_read_model_row_count:
+      fixtures?.summary?.native_semantic_unavailable_read_model_row_count ?? null,
+    native_semantic_unavailable_rag_lite_row_count:
+      fixtures?.summary?.native_semantic_unavailable_rag_lite_row_count ?? null,
+    native_fallback_only_read_model_row_count:
+      fixtures?.summary?.native_fallback_only_read_model_row_count ?? null,
+    native_fallback_only_rag_lite_row_count:
+      fixtures?.summary?.native_fallback_only_rag_lite_row_count ?? null,
+  };
+  const base = {
+    schema_version: VALIDATOR_SCHEMA_VERSION,
+    generated_at: fixtures?.generated_at ?? DEFAULT_GENERATED_AT,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    depends_on_issues: [...DEPENDS_ON_ISSUES],
+    validator_status: status,
+    summary,
+    checks,
+    errors: uniqueErrors,
+    absence_readback: {
+      semantic_unavailable_native_absent:
+        summary.native_semantic_unavailable_read_model_row_count === 0 &&
+        summary.native_semantic_unavailable_rag_lite_row_count === 0,
+      fallback_only_native_absent:
+        summary.native_fallback_only_read_model_row_count === 0 &&
+        summary.native_fallback_only_rag_lite_row_count === 0,
+      derived_fixture_policy:
+        'semantic_unavailable and fallback_only are frontend_projection fixtures derived from preserved real rows when native rows are absent.',
+    },
+  };
+  return {
+    ...base,
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        schema_version: base.schema_version,
+        validator_status: base.validator_status,
+        summary: base.summary,
+        checks: base.checks,
+        errors: base.errors,
+      }),
+    },
+  };
+}
+
+function buildReadback({ fixtures, manifest, validatorResult }) {
+  return `# QuestionRuntimePayload Frontend Fixtures Readback
+
+Issue: #${ISSUE}
+Parent: #${PARENT_ISSUE}
+Depends on: #${DEPENDS_ON_ISSUES.join(', #')}
+Validation status: \`${validatorResult.validator_status}\`
+
+## Artifact Inventory
+
+- Fixtures: \`${fixtures.output_artifacts.fixtures}\`
+- Manifest: \`${fixtures.output_artifacts.manifest}\`
+- Validator: \`${fixtures.output_artifacts.validator}\`
+- Readback: \`${fixtures.output_artifacts.readback}\`
+
+## Scope Boundary
+
+- Full frontend UI integration performed: \`${fixtures.frontend_ui_integration_performed}\`
+- Production Supabase mutation: \`false\`
+- RAG index or vector-store mutation: \`false\`
+
+## Fixture Summary
+
+- Fixture count: \`${fixtures.summary.fixture_count}\`
+- Required states covered: \`${fixtures.summary.required_state_count}\`
+- Derived frontend projection fixtures: \`${fixtures.summary.derived_fixture_count}\`
+- RAG eligible fixtures: \`${fixtures.summary.rag_eligible_fixture_count}\`
+- RAG ineligible fixtures: \`${fixtures.summary.rag_ineligible_fixture_count}\`
+- Attemptable fixtures: \`${fixtures.summary.attemptable_fixture_count}\`
+- Degraded fixtures: \`${fixtures.summary.degraded_fixture_count}\`
+- Blocked fixtures: \`${fixtures.summary.blocked_fixture_count}\`
+
+## Native Absence Verification
+
+- all-3530 semantic_context.status unavailable rows: \`${fixtures.summary.native_semantic_unavailable_read_model_row_count}\`
+- RAG-LITE read-path unavailable rows: \`${fixtures.summary.native_semantic_unavailable_rag_lite_row_count}\`
+- all-3530 fallback_only display rows: \`${fixtures.summary.native_fallback_only_read_model_row_count}\`
+- RAG-LITE fallback_only rows: \`${fixtures.summary.native_fallback_only_rag_lite_row_count}\`
+
+\`semantic_unavailable\` and \`fallback_only\` are marked as \`frontend_projection\` fixtures because those native row postures are absent from the checked-in all-3530 and RAG-LITE read-path rows. They are derived from preserved real source rows and the manifest does not claim the full read model natively contains those postures.
+
+## Fixture Manifest
+
+${manifest.fixture_manifest.map((entry) => (
+  `- ${entry.fixture_id}: source_row=\`${entry.source_row_id}\`, derivation=\`${entry.source_derivation_kind}\`, display=\`${entry.display_posture}\`, semantic=\`${entry.semantic_context_status}\`, rag_eligible=\`${entry.rag_eligible}\``
+)).join('\n')}
+
+## Validator
+
+${validatorResult.checks.map((checkItem) => `- ${checkItem.id}: ${checkItem.status}`).join('\n')}
+`;
+}
+
+export function buildQuestionRuntimePayloadFrontendFixtures(options = {}) {
+  const root = rootFromOptions(options);
+  const paths = pathsFromOptions(options);
+  const generatedAt = generatedAtFromOptions(options);
+  const readPath = options.readPath ?? readJsonInput(root, paths.ragLiteReadPathIn);
+  const all3530Result = options.all3530Result ?? buildQuestionRuntimePayloadAll3530({
+    root,
+    generatedAt,
+  });
+  const schema = all3530Result.adapterResult?.inputs?.schema ?? null;
+  const boundary = all3530Result.adapterResult?.inputs?.boundary ?? null;
+  const compactRowsByQuestion = mapByQuestion(all3530Result.readModel?.rows);
+  const candidatesByQuestion = mapCandidatesByQuestion(
+    all3530Result.adapterResult?.candidates?.payload_candidates,
+  );
